CREATE POLICY social_story_media_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='social-stories' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN('jpg','jpeg','png','webp'));
CREATE POLICY social_story_media_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='social-stories' AND EXISTS(SELECT 1 FROM public.social_stories s WHERE s.media_path=name AND s.expires_at>now() AND (s.user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.social_conversations c WHERE auth.uid() IN(c.member_a,c.member_b) AND s.user_id IN(c.member_a,c.member_b)))));
CREATE POLICY social_story_media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='social-stories' AND (storage.foldername(name))[1]=auth.uid()::text);